const input = $input.first().json;
const out = { route: 'error', cmd: 'error', sessionId: '', message: '', raw: '', exact: '', email: '', password: '', error: '' };
const fail = (msg) => {
  // jamais de mot de passe ni de texte brut dans une branche d'erreur
  Object.assign(out, { route: 'error', cmd: 'error', error: msg, password: '', message: '', raw: '' });
  return [{ json: out }];
};

// 1. L'identifiant de session fait office de jeton : on refuse les valeurs devinables.
const sessionId = typeof input.sessionId === 'string' ? input.sessionId : '';
if (!/^[A-Za-z0-9_-]{32,64}$/.test(sessionId)) {
  return fail('Session invalide : rechargez la page du chat.');
}
out.sessionId = sessionId;

// 2. Nettoyage du texte : Unicode normalisé, caractères de contrôle et invisibles retirés.
let text = typeof input.chatInput === 'string' ? input.chatInput : '';
text = text.normalize('NFKC')
  .replace(/[\u200b-\u200f\u202a-\u202e\u2060-\u2064\ufeff\u00ad]/g, '')  // invisibles : supprim\u00e9s (sinon "ig\u200bnore" contourne le filtre)
  .replace(/[\u0000-\u001f\u007f\u2028\u2029]/g, ' ')
  .replace(/\u2019/g, "'")
  .trim();
if (!text) return fail('Message vide.');
if (text.length > 1000) return fail('Message trop long (1000 caractères maximum).');

const strip = (s) => s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const EMAIL_RE = /^[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$/;
const bytes = (s) => new TextEncoder().encode(s).length;
const pwdError = (pwd, email) => {
  if (bytes(pwd) > 72) return 'Mot de passe trop long (72 octets maximum).';
  if (pwd.length < 12) return 'Mot de passe trop court (12 caractères minimum).';
  const classes = [/[a-z]/, /[A-Z]/, /[0-9]/, /[^A-Za-z0-9]/].filter((r) => r.test(pwd)).length;
  if (classes < 3) return 'Mot de passe trop faible : mélangez au moins 3 types parmi minuscules, majuscules, chiffres et symboles.';
  const name = email.split('@')[0].toLowerCase();  // ignoré s'il est trop court (ex. a.a@…)
  if (name.length >= 4 && pwd.toLowerCase().includes(name)) return 'Le mot de passe ne doit pas contenir votre identifiant email.';
  return '';
};

const parts = text.split(/\s+/);
const head = strip(parts[0]);
const exact = strip(text).replace(/[.!?\s]+$/, '');
// raw : texte complet, utilisé quand le message répond à une étape guidée (email, mot de passe…)
out.raw = text;
out.exact = exact;

const START_REGISTER = ['inscription', "s'inscrire", 'sinscrire', "je veux m'inscrire", 'je veux minscrire',
  'creer un compte', 'creer mon compte', 'nouveau compte', 'sign up', 'register'];
const START_LOGIN = ['connexion', 'se connecter', 'je veux me connecter', "m'identifier", 'login', 'log in', 'sign in'];

if (START_REGISTER.includes(exact)) {
  Object.assign(out, { route: 'session', cmd: 'register_start' });
} else if (START_LOGIN.includes(exact)) {
  Object.assign(out, { route: 'session', cmd: 'login_start' });
} else if (['annuler', 'cancel', 'stop'].includes(exact)) {
  Object.assign(out, { route: 'session', cmd: 'cancel' });
} else if (head === 'inscription') {
  // inscription EMAIL MOT_DE_PASSE j'accepte
  if (parts.length !== 4) return fail("Pour créer un compte, tapez simplement « inscription » : je vous guide étape par étape.");
  const email = parts[1].toLowerCase();
  const password = parts[2];
  if (email.length > 254 || !EMAIL_RE.test(email)) return fail('Adresse email invalide.');
  const pe = pwdError(password, email);
  if (pe) return fail(pe);
  if (!["accepte", "j'accepte", 'jaccepte'].includes(strip(parts[3]))) {
    return fail("Le consentement est obligatoire : terminez la commande par « j'accepte ».");
  }
  Object.assign(out, { route: 'register', cmd: 'register', email, password, raw: '' });
} else if (head === 'connexion') {
  // connexion EMAIL MOT_DE_PASSE
  if (parts.length !== 3) return fail('Pour vous connecter, tapez simplement « connexion » : je vous guide étape par étape.');
  const email = parts[1].toLowerCase();
  const password = parts[2];
  if (email.length > 254 || !EMAIL_RE.test(email) || bytes(password) > 72) {
    return fail('Pour vous connecter, tapez simplement « connexion » : je vous guide étape par étape.');
  }
  Object.assign(out, { route: 'login', cmd: 'login', email, password, raw: '' });
} else {
  out.route = 'session';
  if (['deconnexion', 'logout'].includes(exact)) out.cmd = 'logout';
  else if (exact === 'supprimer mon compte') out.cmd = 'delete_request';
  else if (exact === 'confirmer suppression') out.cmd = 'delete_confirm';
  else if (['mes donnees', 'exporter mes donnees'].includes(exact)) out.cmd = 'export';
  else if (['aide', 'help'].includes(exact)) out.cmd = 'help';
  else { out.cmd = 'chat'; out.message = text; }
}
return [{ json: out }];

