const s = $input.first().json;
let action;
if (['register_start', 'login_start', 'cancel'].includes(a.cmd)) action = a.cmd;
else if (!s.user_id && s.step) action = s.step;   // le message répond à l'étape guidée en cours
else if (!s.user_id) action = 'anonymous';
else action = a.cmd;
return [{ json: { action, user_id: s.user_id || null, pending_email: s.email || '' } }];

