WITH up AS (
  INSERT INTO auth_pending (chat_session_id, step) VALUES ($1::text, $2::text)
  ON CONFLICT (chat_session_id) DO UPDATE SET step = EXCLUDED.step, email = NULL, created_at = now()
  RETURNING 1
)
SELECT 'done' AS status FROM up;

WITH up AS (
  INSERT INTO auth_pending (chat_session_id, step) VALUES ($1::text, $2::text)
  ON CONFLICT (chat_session_id) DO UPDATE SET step = EXCLUDED.step, email = NULL, created_at = now()
  RETURNING 1
)
SELECT 'done' AS status FROM up;

WITH upd AS (
  UPDATE auth_pending SET step = 'register_password', created_at = now()
  WHERE chat_session_id = $1::text AND $2::text IN ('j''accepte', 'jaccepte', 'accepte', 'oui', 'oui j''accepte')
  RETURNING 1
)
SELECT EXISTS (SELECT 1 FROM upd) AS ok;

