let error = '';
if (bytes > 72) error = 'Mot de passe trop long (72 octets maximum).';
else if (raw.length < 12) error = 'Mot de passe trop court (12 caractères minimum).';
else if (classes < 3) error = 'Mot de passe trop faible : mélangez au moins 3 types parmi minuscules, majuscules, chiffres et symboles.';
else if (email && email.split('@')[0].length >= 4 && raw.toLowerCase().includes(email.split('@')[0])) error = 'Le mot de passe ne doit pas contenir votre identifiant email.';
