WITH ok AS (SELECT 1 WHERE $3::text = ''),
new_user AS (
  INSERT INTO users (email, password_hash, consent_given_at, consent_version)
  SELECT $1::text, crypt($2::text, gen_salt('bf', 12)), now(), 'v1' FROM ok
  ON CONFLICT (email) DO NOTHING
  RETURNING id
), prefs AS (
  INSERT INTO preferences (user_id) SELECT id FROM new_user
), log_ok AS (
  INSERT INTO audit_log (event, user_id, details) SELECT 'register_ok', id, '{}'::jsonb FROM new_user
), log_dup AS (
  INSERT INTO audit_log (event, details)
  SELECT 'register_duplicate', '{}'::jsonb WHERE EXISTS (SELECT 1 FROM ok) AND NOT EXISTS (SELECT 1 FROM new_user)
), done AS (
  DELETE FROM auth_pending WHERE chat_session_id = $4::text AND EXISTS (SELECT 1 FROM ok)
)
SELECT 'done' AS status;

WITH d AS (DELETE FROM sessions WHERE chat_session_id = $1::text RETURNING user_id),
l AS (INSERT INTO audit_log (event, user_id, details) SELECT 'logout', user_id, '{}'::jsonb FROM d)
SELECT 'done' AS status;

WITH del AS (DELETE FROM users WHERE id = $1::uuid RETURNING id),
l AS (INSERT INTO audit_log (event, user_id, details) SELECT 'account_deleted', id, '{}'::jsonb FROM del)
SELECT count(*)::int AS deleted FROM del;

